import {join,resolve} from 'node:path';
import {writeFileSync} from 'node:fs';
import {OwnedDatabase} from '../src/infrastructure/database/owned-database';
import {createSchema} from '../src/infrastructure/database/schema';
import {rebuildProjectionsWithReport} from '../src/infrastructure/database/event-log';
export async function crossRuntime(executable:string,dir:string){
 const path=join(dir,'cross.db'),log=join(dir,'events-cross.jsonl'),db=new OwnedDatabase(path);
 try{createSchema(db);writeFileSync(log,JSON.stringify({uuid:'synthetic',type:'preference',project:'synthetic',content:'synthetic',observedAt:'2026-01-01T00:00:00Z',metadata:{confidence:0.9000000000000001}}));await rebuildProjectionsWithReport(db,log);db.exec('UPDATE facts SET id=9007199254740993');await rebuildProjectionsWithReport(db,log);}finally{db.close();}
 const script=join(dir,'cross.ts');writeFileSync(script,'import {OwnedDatabase} from '+JSON.stringify(resolve('src/infrastructure/database/owned-database.ts'))+';import {assertAutomaticProjectionReplay} from '+JSON.stringify(resolve('src/infrastructure/database/projection-state.ts'))+';const db=new OwnedDatabase('+JSON.stringify(path)+');try{assertAutomaticProjectionReplay(db);console.log("Cross-runtime receipt admitted");}finally{db.close();}');
 const result=Bun.spawnSync([executable,script],{stdout:'pipe',stderr:'pipe',timeout:15000});
 const output=new TextDecoder().decode(result.stdout)+new TextDecoder().decode(result.stderr);
 if(result.exitCode!==0)throw Error('Cross-runtime receipt mismatch '+output);
 return {command:[executable,script],exit:result.exitCode,output,source:await Bun.file(import.meta.path).text(),script:await Bun.file(script).text()};
}

