import {strict as assert} from 'node:assert';
import {readFileSync,writeFileSync,existsSync,statSync} from 'node:fs';
import {join} from 'node:path';
import {Database} from 'bun:sqlite';
import {createOwnedTestDirectory} from '../tests/helpers/owned-test-directory';
const storage=createOwnedTestDirectory('memory-admission-probe-'),file=join(storage.dir,'coordination.db'),script=join(storage.dir,'actor.ts');
const init=new Database(file);init.exec('CREATE TABLE authority(version INTEGER NOT NULL);INSERT INTO authority VALUES(1)');init.close();
const identity=statSync(file,{bigint:true});
const source=`
import {Database} from 'bun:sqlite';import {writeFileSync,existsSync,appendFileSync} from 'node:fs';
const [file,ready,release,mode,marker]=process.argv.slice(2);const db=new Database(file);db.exec('PRAGMA busy_timeout=0');let held=false;
try{db.exec('BEGIN IMMEDIATE');held=true;if(mode==='contender'){appendFileSync(marker,'entered\\n');console.log(JSON.stringify({entered:true}));}
else{writeFileSync(ready,'ready');const deadline=Date.now()+10000,word=new Int32Array(new SharedArrayBuffer(4));while(!existsSync(release)){if(Date.now()>deadline)throw Error('barrier timeout');Atomics.wait(word,0,0,5);}if(mode==='error')throw Error('synthetic operation failure');console.log(JSON.stringify({released:true}));}}
catch(error){console.log(JSON.stringify({entered:false,code:error.code,error:error.message}));}
finally{if(held)db.exec('ROLLBACK');db.close();}
`;
writeFileSync(script,source);const runs:unknown[]=[];
try{for(const mode of ['normal','error','kill']){
 const ready=join(storage.dir,mode+'-ready'),release=join(storage.dir,mode+'-release'),marker=join(storage.dir,mode+'-marker');
 const env={...process.env,TEMP:storage.dir,TMP:storage.dir,TMPDIR:storage.dir};
 const child=Bun.spawn([process.execPath,script,file,ready,release,mode,marker],{stdout:'pipe',stderr:'pipe',timeout:15000,env});
 const stdout=new Response(child.stdout).text(),stderr=new Response(child.stderr).text();
 try{
  const deadline=Date.now()+10000;while(!existsSync(ready)){if(Date.now()>deadline||child.exitCode!==null)throw Error('Owner did not acquire '+await stderr);await Bun.sleep(5);}
  const attempt=()=>{const child=Bun.spawnSync([process.execPath,script,file,ready,release,'contender',marker],{stdout:'pipe',stderr:'pipe',timeout:5000,env});assert.equal(child.exitCode,0);return JSON.parse(new TextDecoder().decode(child.stdout));};
  const denied=attempt();assert.equal(denied.entered,false);assert.equal(denied.code,'SQLITE_BUSY');assert.equal(existsSync(marker),false);
  if(mode==='kill')child.kill();else writeFileSync(release,'continue');
  const ownerExit=await child.exited;const ownerOutput=await stdout,ownerError=await stderr;
  if(mode==='normal')assert.equal(JSON.parse(ownerOutput).released,true);if(mode==='error')assert.equal(JSON.parse(ownerOutput).error,'synthetic operation failure');
  const acquired=attempt();assert.equal(acquired.entered,true);assert.equal(readFileSync(marker,'utf8'),'entered\n');
  const after=statSync(file,{bigint:true});assert.equal(after.dev,identity.dev);assert.equal(after.ino,identity.ino);
  runs.push({mode,denied,ownerExit,ownerOutput,ownerError,acquired,sameFile:true});
 }finally{if(child.exitCode===null){child.kill();await child.exited;}}
}
 const report={recordedAt:new Date().toISOString(),runtime:Bun.version,platform:process.platform,runs,bytes:statSync(file).size,source:readFileSync(import.meta.path,'utf8'),childSource:source,limits:['Synthetic SQLite backend only; source identity, ownership, command wiring and complete writer adoption are not proved.','Process termination is not power loss or partial append durability.']};
 writeFileSync('.git/q100-admission-probe-'+Bun.version+'.json',JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify({runtime:Bun.version,cases:runs.length,bytes:report.bytes,result:'pass'}));
}finally{storage.cleanup();}

