  const acquired=attempt();assert.equal(acquired.entered,true);assert.equal(readFileSync(marker,'utf8'),'entered\n');
  const after=statSync(file,{bigint:true});assert.equal(after.dev,identity.dev);assert.equal(after.ino,identity.ino);
  runs.push({mode,denied,ownerExit,ownerOutput,ownerError,acquired,sameFile:true});
 }finally{if(child.exitCode===null){child.kill();await child.exited;}}
}
 const report={recordedAt:new Date().toISOString(),runtime:Bun.version,platform:process.platform,runs,bytes:statSync(file).size,source:readFileSync(import.meta.path,'utf8'),childSource:source,limits:['Synthetic SQLite backend only; source identity, ownership, command wiring and complete writer adoption are not proved.','Process termination is not power loss or partial append durability.']};
 writeFileSync('.git/q100-admission-adapter-probe-'+Bun.version+'.json',JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify({runtime:Bun.version,cases:runs.length,bytes:report.bytes,result:'pass'}));
}finally{storage.cleanup();}

