import {SqliteOperationAdmission} from "C:/Projects/memory-nexus/src/infrastructure/database/sqlite-operation-admission.ts";
import {writeFileSync,existsSync,appendFileSync} from 'node:fs';
const [file,ready,release,mode,marker]=process.argv.slice(2);
try{const result=await new SqliteOperationAdmission(file).run(async()=>{
 if(mode==='contender'){appendFileSync(marker,'entered\n');return {entered:true};}
 writeFileSync(ready,'ready');const deadline=Date.now()+10000,word=new Int32Array(new SharedArrayBuffer(4));while(!existsSync(release)){if(Date.now()>deadline)throw Error('barrier timeout');Atomics.wait(word,0,0,5);}
 if(mode==='error')throw Error('synthetic operation failure');return {released:true};
});console.log(JSON.stringify(result));}
catch(error){console.log(JSON.stringify({entered:false,code:error.cause?.code,error:error.message}));}

